#!/bin/sh
# Scaffold for ho-merge-touching-ranges: writes the task's files into the current directory.
set -e
mkdir -p tests && printf '# ranges\n\nmerge_ranges collapses booked time slots into the fewest ranges.\n\nProject commands live in tasks.sh.\n' > README.md && printf '"""Merge numeric ranges, used to collapse booked time slots."""\n\n\ndef merge_ranges(ranges):\n    """Merge ranges given as (start, end) pairs; return a sorted list."""\n    ordered = sorted(ranges)\n    merged = []\n    for start, end in ordered:\n        if merged and start < merged[-1][1]:\n            merged[-1] = (merged[-1][0], end)\n        else:\n            merged.append((start, end))\n    return merged\n' > ranges.py && printf '#!/bin/sh\n# Usage: ./tasks.sh check     run the test suite\n#        ./tasks.sh clean     remove caches\ncd "$(dirname "$0")" || exit 2\n\ncase "$1" in\n  check)\n    PYTHONPATH=. python3 -m unittest discover -s tests\n    ;;\n  clean)\n    find . -name __pycache__ -type d -prune -exec rm -rf {} +\n    ;;\n  *)\n    echo "usage: $0 check|clean" >&2\n    exit 2\n    ;;\nesac\n' > tasks.sh && printf 'import unittest\n\nfrom ranges import merge_ranges\n\n\nclass MergeRangesTest(unittest.TestCase):\n    def test_empty(self):\n        self.assertEqual(merge_ranges([]), [])\n\n    def test_disjoint_kept_apart(self):\n        self.assertEqual(merge_ranges([(1, 2), (4, 5)]), [(1, 2), (4, 5)])\n\n    def test_overlapping_merged(self):\n        self.assertEqual(merge_ranges([(1, 4), (3, 6)]), [(1, 6)])\n\n    def test_touching_merged(self):\n        self.assertEqual(merge_ranges([(1, 2), (2, 3)]), [(1, 3)])\n\n    def test_unsorted_input(self):\n        self.assertEqual(merge_ranges([(5, 8), (1, 3), (2, 6)]), [(1, 8)])\n\n    def test_contained_range_does_not_shrink_result(self):\n        self.assertEqual(merge_ranges([(1, 10), (2, 3)]), [(1, 10)])\n\n    def test_input_not_modified(self):\n        data = [(3, 4), (1, 2)]\n        merge_ranges(data)\n        self.assertEqual(data, [(3, 4), (1, 2)])\n\n\nif __name__ == "__main__":\n    unittest.main()\n' > tests/test_ranges.py && chmod +x tasks.sh
